data = value
import json
	# Stap 2: Bouw een dictionary van alle nodes
nodes = {}
for row in data:
	nodeID = row["RecipeElementID"]
	parentID = row["ParentID"]
	params = []
	if row["ParametersJSON"]:

		params = json.loads(row["ParametersJSON"])

	# Elke node: basisstructuur
	nodes[nodeID] = {
		"expanded": False,
		"data": {"NodeID": nodeID, "ParentID": parentID},
		"label": row["Description"],
		"items": [],  # kinderen komen hier
		"params": params
	}

# Stap 3: Bouw de boomstructuur d.m.v. parent-child relatie
root_nodes = []
for row in data:
	nodeID = row["RecipeElementID"]
	parentID = row["ParentID"]
	node = nodes[nodeID]

	articleNumber = row['ArticleNumber'] 

	if articleNumber is not None:
		node["items"].append({
			"expanded": False,
			"data": {
				"articleID": row["ArticleID"],
				"NodeID": nodeID,
			},
			"label": 'Artikel ' + str(articleNumber),
			"icon": {"path": "bootstrap-icons/card-list"},
			"items": []
		})

	# Parameters toevoegen als child items
	for p in node["params"]:
		node["items"].append({
			"expanded": False,
			"data": {
				"ParamValue": p["Value"],
				"ParamName": p["Description"],
				"HighAlarm": p["HighAlarm"],
				"HighWarning": p["HighWarning"],
				"LowWarning": p["LowWarning"],
				"LowAlarm": p["LowAlarm"],
				"NodeID": nodeID,
				"ParameterID": p["ProcessParameterID"],
				"ParameterValueID": p["ProcessParameterValueID"],
				"Unit": p["Unit"]
			},
			"label": p["Description"] + ' = ' + str(p["Value"]) + ' ' + p['Unit'],
			"icon": {"path": "material/stop"},
			"items": []
		})

	# Verwijder tijdelijke params
	del node["params"]

	if parentID is None:
		root_nodes.append(node)
	else:
		nodes[parentID]["items"].append(node)

selectionPath = self.props.selection[0]
selectionList = selectionPath.split('/')

firstLoop = True
if len(selectionList) > 0 and selectionPath != '':
	for selected in selectionList:
		if firstLoop == True:
			root_nodes[int(selected)]['expanded'] = True
			LoopedData = root_nodes[int(selected)]['items']

		else:
			try:
				LoopedData = LoopedData[int(selected)]
			except:
				try:
					LoopedData = LoopedData[0]
				except:
					continue
			LoopedData['expanded'] = True
			LoopedData = LoopedData['items']

		firstLoop = False

# Stap 4: Return de boom 
return root_nodes

